import{_ as a,o as r,c as i,a5 as o}from"./chunks/framework.DrDMl0tG.js";const h=JSON.parse('{"title":"Example targets","description":"","frontmatter":{},"headers":[],"relativePath":"sections/rayrai/Examples.md","filePath":"sections/rayrai/Examples.md"}'),t={name:"sections/rayrai/Examples.md"};function s(l,e,d,n,c,m){return r(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="example-targets" tabindex="-1">Example targets <a class="header-anchor" href="#example-targets" aria-label="Permalink to &quot;Example targets&quot;">​</a></h1><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h2><p>Rayrai examples are documented in <a href="./../Examples.html">Examples</a>. Each example page includes a short explanation, CMake target, and build-tree usage.</p><p>Quick map to the current rayrai-related targets:</p><ul><li><code>rayrai_tcp_viewer</code>: source-built viewer for <code>raisim::RaisimServer</code> scenes.</li><li><code>rayrai_basic_scene</code>: minimal ImGui + SDL2 app that loads Go1 on a checkerboard ground and runs the standard update loop.</li><li><code>rayrai_complete_showcase</code>: broad in-process scene with a sensored ANYmal that combines RGB/depth cameras, raw buffer readback, LiDAR visualization, camera frustums, instancing, and custom visuals.</li><li><code>rayrai_rgb_camera</code> / <code>rayrai_depth_camera</code> / <code>rayrai_lidar_pointcloud</code> / <code>rayrai_aruco_marker</code>: robot-attached RGB rendering, depth readback, LiDAR point-cloud visualization, and marker rendering.</li><li><code>rayrai_custom_visuals</code> / <code>rayrai_instancing_grid</code> / <code>rayrai_pointcloud_animation</code>: visual primitives, instancing, and dynamic point-cloud streaming.</li><li><code>rayrai_pbr_material_grid</code> / <code>rayrai_pbr_texture_maps</code> / <code>rayrai_quality_lighting</code>: bundled glTF PBR sample assets, texture maps, HDR image-based lighting, quality presets, and additional-light configurations.</li><li><code>rayrai_nested_glass</code>: nested water, glass, and air with automatic geometry tracing; see <a href="./../examples/rayrai/rayrai_nested_glass.html">Rayrai Example: Nested Glass</a>.</li><li><code>rayrai_visual_asset_support</code>: textured URDF visual meshes (OBJ/DAE with image textures) rendered separately from their collision geometry.</li><li><code>rayrai_blue_wall_scene</code>: the authored Poly Haven &quot;Blue Wall&quot; scene, loaded from <code>rsc/rayrai/blue_wall/blue_wall.rscene</code> with its light sidecar and HDR environment. The example reads that file with its own parser, not with <code>raisim::World(path)</code>.</li><li><code>rayrai_coacd_mesh_approximation</code>: in-process comparison of source meshes and CoACD convex approximation parts generated through <code>World::addMesh</code>.</li><li><code>rayrai_runtime_scene_editing</code>: snapshots, cloning, removal, stable object ids, and collision-filter changes in a running world.</li><li><code>rayrai_rolling_spinning_friction</code> / <code>rayrai_swept_ccd</code>: physics-focused scenes that visualize rolling/spinning friction and swept CCD.</li><li><code>rayrai_motor_operating_region</code>: a randomly actuated fixed-base quadruped rig with torque-speed plots of each motor&#39;s operating region; see <a href="./../examples/rayrai/rayrai_motor_operating_region.html">Rayrai Example: Motor Operating Region</a>.</li><li><code>rayrai_tendons</code>: automatic spatial tendon rendering for the elastic, pulley, and coupling scenes; see <a href="./../tendons/Examples.html">Tendon examples and Rayrai</a>.</li><li><code>rayrai_forest</code>: dense instanced vegetation on a heightmap with automatic mesh LOD, foliage wind and shadows, and asynchronous loading; see <a href="./../examples/rayrai/rayrai_forest.html">Rayrai Example: Forest</a>.</li><li><code>rayrai_forest_from_rscene</code>: the same forest loaded from its <code>.rscene</code> file with <code>raisim::World(path)</code>, shown by a <code>RayraiWindow</code> (requires v2.8.2, not yet released); see <a href="./../examples/rayrai/rayrai_forest_from_rscene.html">Rayrai Example: Forest From .rscene</a> and <a href="./../RsceneFile.html">.rscene File</a>.</li><li><code>rayrai_city</code>: a photoreal city built from free Poly Haven, BlendKit and Sketchfab assets and stored as a <code>.rscene</code> file, with an ANYmal C quadruped on the street; see <a href="./../examples/rayrai/rayrai_city.html">Rayrai Example: City</a>.</li><li><code>rayrai_city_from_xml</code>: the same city and robot from a RaiSim XML world file that describes the robot and includes the <code>.rscene</code> file; see <a href="./../examples/rayrai/rayrai_city_from_xml.html">Rayrai Example: City From XML</a>.</li><li><code>rayrai_warehouse</code>: a photoreal warehouse of pallet racks, forklifts and a dock area built from free Poly Haven and Sketchfab assets and generated racking, stored as a <code>.rscene</code> file, with an ANYmal C quadruped in an aisle; see <a href="./../examples/rayrai/rayrai_warehouse.html">Rayrai Example: Warehouse</a>.</li><li><code>rayrai_water_pond</code>: a pond in a meadow drawn with rayrai water, with trees, mossy rocks and a jetty on its banks; see <a href="./../examples/rayrai/rayrai_water_pond.html">Rayrai Example: Water Pond</a>.</li><li><code>rayrai_water_stream</code>: a creek simulated as flowing water runs down a hillside into a pool, and wooden balls float down it with the buoyancy and drag of the simulated current; see <a href="./../examples/rayrai/rayrai_water_stream.html">Rayrai Example: Water Stream</a>.</li><li><code>rayrai_offroad_buggy</code>: an off-road buggy driven with the arrow keys on a dirt race circuit with a pit lane, tyre walls, hay bales and cones that it can knock over, and spectator stands. Its double wishbones, coilovers and rack-and-pinion steering are one URDF closed by pin, equality and mimic constraints; the coil springs are drawn at their simulated length and coloured by their compression. See <a href="./../examples/rayrai/rayrai_offroad_buggy.html">Rayrai Example: Off-Road Buggy</a>.</li><li>glTF/GLB scene import with authored lights and reflection-probe sidecars is described in <a href="./../examples/rayrai/rayrai_blender_scene_import.html">Rayrai Workflow: Blender Scene Import</a>.</li><li>OpenUSD visual meshes can be loaded through <code>RayraiWindow::addVisualMesh</code>; see <a href="./../OpenUSD.html">OpenUSD Loading</a> for importer scope and runtime layout.</li></ul><p>For manual regression checks of depth images after heightmap and primitive replacement, see <a href="./../debug_tools/rayrai_heightmap_replacement.html">Debug Tool: Heightmap Replacement</a>. This optional debug tool is built with <code>RAISIM_DEBUG_TOOLS=ON</code>.</p>',6)])])}const _=a(t,[["render",s]]);export{h as __pageData,_ as default};
